import React from 'react';

export default function Logo({ 
  className = "", 
  width = "100%", 
  height = "100%" 
}: { 
  className?: string; 
  width?: number | string; 
  height?: number | string; 
}) {
  return (
    <svg 
      xmlns="http://www.w3.org/2000/svg" 
      viewBox="0 0 1024 1024" 
      className={className}
      width={width} 
      height={height}
    >
      <image href="data:image/png;base64," width="1024" height="1024" />
    </svg>
  );
}
